<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';
import {request} from './workbench-api';
const props=defineProps({bases:{type:Array,default:()=>[]}}),emit=defineEmits(['task','review','document']);
const base=ref(''),summary=ref(null),diagnostics=ref(null),trace=ref(null),error=ref(''),busy=ref(false);let seq=0,traceSeq=0;
async function load(probe=false){const token=++seq;busy.value=true;summary.value=null;diagnostics.value=null;error.value='';try{const [s,d]=await Promise.all([request('/quality/summary'+(base.value?'?knowledge_base_id='+encodeURIComponent(base.value):'')),request('/diagnostics?check_services='+probe)]);if(token!==seq)return;summary.value=s;diagnostics.value=d;}catch(e){if(token===seq)error.value=e.message;}finally{if(token===seq)busy.value=false;}}
async function inspect(id){const token=++traceSeq;trace.value=null;try{const r=await request('/diagnostics/traces/'+encodeURIComponent(id));if(token===traceSeq)trace.value=r;}catch(e){if(token===traceSeq)error.value=e.message;}}
const labels={ready:'可用',not_configured:'未配置',external_not_probed:'外部服务未探测',unavailable:'暂不可用'};
watch(base,()=>load(false),{immediate:true});onBeforeUnmount(()=>{seq++;traceSeq++;});
</script>
<template><section class="wb-card"><small>QUALITY AND DIAGNOSTICS</small><h2>质量统计与统一排错</h2><p>统计当前有效资料；来源审核、模型观察和整份资料发布分别计数。错误入口保留 Trace 与任务记录。</p><div class="wb-actions"><select v-model="base" aria-label="质量统计知识库"><option value="">全部知识库</option><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select><button class="wb-button" :disabled="busy" @click="load(false)">刷新质量统计</button><button class="wb-button" :disabled="busy" @click="load(true)">检查本机服务</button></div><div v-if="error" role="alert" class="wb-alert error">{{error}}<p>可在项目目录运行 <code>python scripts/manage_workbench.py check</code> 检查环境与启停记录。</p></div><p v-if="busy">正在读取实际状态…</p><template v-if="summary"><p class="wb-muted">{{new Date(summary.checked_at).toLocaleString('zh-CN')}} · 当前语料版本 {{summary.corpus_generation}}</p><div class="stats"><article><small>有效文档 / 图片</small><strong>{{summary.documents}} / {{summary.images}}</strong></article><article><small>当前 Chunk / 已索引</small><strong>{{summary.active_chunks}} / {{summary.current_indexed_chunks}}</strong></article><article><small>图片描述 / 有效图片</small><strong>{{summary.described_images}} / {{summary.images}}</strong></article><article><small>已核对画面标签</small><strong>{{summary.source_reviewed_image_labels}}</strong></article><article><small>处理失败 / 缺少块索引</small><strong>{{summary.failed_documents}} / {{summary.missing_chunk_indexes}}</strong></article><article><small>图文语义索引 / 缺少描述</small><strong>{{summary.cross_modal_indexed_images}} / {{summary.missing_image_descriptions}}</strong></article></div><section v-if="summary.issues.length"><h3>需要处理的资料（最多显示 20 份）</h3><article v-for="d in summary.issues" :key="d.document_id" class="event"><strong>{{d.source_name}}</strong><p>{{d.reasons.map(r=>({processing_failed:'解析失败',missing_text_index:'当前块缺索引',missing_image_description:'图片缺少描述'})[r]||r).join(' / ')}}</p><button class="wb-button tiny" @click="emit('document',d)">定位文档与 Chunk</button></article></section><div class="panels"><section><h3>来源与结构</h3><p>来源未声明版本：{{summary.source_version_not_declared}}（如实统计，本轮不要求补证）</p><p>OCR：识别有字 {{summary.ocr.completed||0}} · 未识别到字 {{summary.ocr.no_text||0}} · 其它 {{Object.entries(summary.ocr).filter(([k])=>!['completed','no_text'].includes(k)).reduce((n,[,v])=>n+v,0)}}</p><p>结构处置：恢复表 {{summary.structure_dispositions.recovered_table||0}} · 已有表替代 {{summary.structure_dispositions.superseded||0}} · 图形依据 {{summary.structure_dispositions.graphic_reference||0}}</p><div class="table-wrap"><table><thead><tr><th>知识库</th><th>文档</th><th>图片</th></tr></thead><tbody><tr v-for="b in summary.by_base" :key="b.knowledge_base_id"><td>{{bases.find(x=>x.id===b.knowledge_base_id)?.name||b.knowledge_base_id}}</td><td>{{b.documents}}</td><td>{{b.images}}</td></tr></tbody></table></div></section><section><h3>当前修订审核记录</h3><p v-for="r in summary.current_evidence_reviews" :key="r.kind+r.decision">{{r.kind==='user_source_review'?'操作审核':'AI 来源审核'}} · {{r.decision}}：{{r.count}}</p><p>画面标签只参与可核查检索，整份资料发布仍由资料审核入口单独记录。</p><h4>最近修正与审核</h4><article v-for="r in summary.recent_source_reviews" :key="r.review_id" class="event"><strong>{{r.reviewer}} · {{r.decision}}</strong><p>{{r.note}}</p><button class="wb-button tiny" @click="emit('review',{document_id:r.document_id})">查看该资料审核与版本</button></article></section></div></template></section>
<section v-if="diagnostics" class="wb-card"><h3>统一排错入口</h3><p>SQLite 检查：{{diagnostics.database.quick_check}} · Python {{diagnostics.environment.python}} · {{diagnostics.environment.platform}} · SQLite {{diagnostics.environment.sqlite}}</p><p v-for="(ready,name) in diagnostics.environment.optional_modules" :key="name">{{name}}：{{ready?'已安装':'未安装（对应可选能力不可用）'}}</p><h4>本机模型服务</h4><p v-if="!diagnostics.services_probed">点击“检查本机服务”进行实际探测；当前没有推断服务可用性。</p><p v-for="s in diagnostics.services" :key="s.service">{{s.service}}：{{labels[s.status]||s.status}} {{s.model||s.error_type||''}}</p><div class="panels"><section><h4>全局失败、部分完成或暂停的任务</h4><article v-for="t in diagnostics.failed_or_paused_tasks" :key="t.task_id" class="event"><strong>{{t.kind}} · {{t.status}}</strong><p>{{t.error}}</p><button class="wb-button tiny" @click="emit('task',t.task_id)">到任务中心查看 / 续跑</button></article><p v-if="!diagnostics.failed_or_paused_tasks.length">当前没有这类任务。</p></section><section><h4>最近失败检索</h4><article v-for="t in diagnostics.failed_traces" :key="t.trace_id" class="event"><strong>{{t.stage||t.error_type||'检索'}} · {{t.code||'未记录错误码'}}</strong><p>{{t.question}}</p><button class="wb-button tiny" @click="inspect(t.trace_id)">查看 {{t.trace_id}}</button></article><p v-if="!diagnostics.failed_traces.length">没有已保存的失败检索。</p></section></div><details v-if="trace" open><summary>Trace {{trace.trace_id}}</summary><pre>{{JSON.stringify(trace,null,2).slice(0,50000)}}</pre><p v-if="JSON.stringify(trace).length>50000">Trace 较长，当前显示前 50,000 字符。</p></details></section></template>
<style scoped>.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:15px 0}.stats article{background:#eef4f9;border:1px solid #dae4ed;border-radius:8px;padding:15px}.stats strong{display:block;font-size:24px;margin-top:6px}.panels{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.panels>section{min-width:0}.event{border-top:1px solid #d9e1e9;padding:12px 0}.event p{margin:8px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:8px;text-align:left;border-bottom:1px solid #dae2eb}p,small,strong,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap;max-height:500px;overflow:auto}@media(max-width:750px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.panels{grid-template-columns:minmax(0,1fr)}}</style>
